        return AiMuxErrorAIAPICallError.fromJson(json);
      case 'AI_RetryError':
        return AiMuxErrorAIRetryError.fromJson(json);
      case 'AI_JSONParseError':
        return AiMuxErrorAIJSONParseError.fromJson(json);
      case 'AI_NoOutputGeneratedError':
        return AiMuxErrorAINoOutputGeneratedError.fromJson(json);
      case 'AI_InvalidResponseDataError':
        return AiMuxErrorAIInvalidResponseDataError.fromJson(json);
      case 'AI_ToolCallNotFoundForApprovalError':
        return AiMuxErrorAIToolCallNotFoundForApprovalError.fromJson(json);
      case 'AI_NoSuchToolError':
        return AiMuxErrorAINoSuchToolError.fromJson(json);
      case 'AI_InvalidToolInputError':
        return AiMuxErrorAIInvalidToolInputError.fromJson(json);
      case 'AI_ToolCallRepairError':
        return AiMuxErrorAIToolCallRepairError.fromJson(json);
      case 'AI_InvalidArgumentError':
        return AiMuxErrorAIInvalidArgumentError.fromJson(json);
      case 'AI_InvalidPromptError':
        return AiMuxErrorAIInvalidPromptError.fromJson(json);
      case 'AI_LoadAPIKeyError':
        return AiMuxErrorAILoadAPIKeyError.fromJson(json);
      case 'AI_LoadSettingError':
        return AiMuxErrorAILoadSettingError.fromJson(json);
      case 'AI_TokenExpiredError':
        return AiMuxErrorAITokenExpiredError.fromJson(json);
      case 'AI_UnsupportedFunctionalityError':
        return AiMuxErrorAIUnsupportedFunctionalityError.fromJson(json);
      case 'AI_NoSuchModelError':
        return AiMuxErrorAINoSuchModelError.fromJson(json);
      case 'AI_NoSuchProviderError':
        return AiMuxErrorAINoSuchProviderError.fromJson(json);
      case 'AI_MissingToolResultsError':
        return AiMuxErrorAIMissingToolResultsError.fromJson(json);
      case 'AI_ToolChoiceViolationError':
        return AiMuxErrorAIToolChoiceViolationError.fromJson(json);
