/// A part of the content text generation returns: the AI SDK's core
/// `ContentPart` (`ai` `generate-text/content-part.ts:12-33`), eleven kinds,
/// separate from the provider's [`GenerateContent`].
///
/// Tool calls are parsed, a provider tool result is a [`TypedToolResult`]
/// or, when the provider marks it as an error, a [`TypedToolError`], and a
/// generated file is wrapped as `{ file, providerMetadata }`, as upstream's
/// `convertLanguageModelContent` builds them
/// (`generate-text/convert-language-model-content.ts`).
sealed class ContentPart {
  const ContentPart();
  String get type;
  factory ContentPart.fromJson(Map<String, dynamic> json) {
    switch (json['type']) {
      case 'text':
        return ContentPartText.fromJson(json);
      case 'custom':
        return ContentPartCustom.fromJson(json);
      case 'reasoning':
        return ContentPartReasoning.fromJson(json);
      case 'reasoning-file':
        return ContentPartReasoningFile.fromJson(json);
      case 'source':
        try {
          return ContentPartSourceUrl.fromJson(json);
        } catch (_) {
          // Try the next shape with this tag.
        }
        return ContentPartSourceDocument.fromJson(json);
      case 'file':
        return ContentPartFile.fromJson(json);
      case 'tool-call':
        return ContentPartToolCall.fromJson(json);
      case 'tool-result':
        return ContentPartToolResult.fromJson(json);
      case 'tool-error':
        return ContentPartToolError.fromJson(json);
      case 'tool-approval-request':
        return ContentPartToolApprovalRequest.fromJson(json);
      case 'tool-approval-response':
        return ContentPartToolApprovalResponse.fromJson(json);
      default:
        throw FormatException('Unknown ContentPart tag: ${json['type']}');
    }
  }

  Map<String, dynamic> toJson();
}

