        return GenerateContentSourceDocument.fromJson(json);
      case 'reasoning':
        return GenerateContentReasoning.fromJson(json);
      case 'file':
        return GenerateContentFile.fromJson(json);
      case 'reasoning-file':
        return GenerateContentReasoningFile.fromJson(json);
      case 'custom':
        return GenerateContentCustom.fromJson(json);
      case 'tool-approval-request':
        return GenerateContentToolApprovalRequest.fromJson(json);
      case 'tool-result':
        return GenerateContentToolResult.fromJson(json);
      default:
        throw FormatException('Unknown GenerateContent tag: ${json['type']}');
    }
  }

  Map<String, dynamic> toJson();
}

