/// User-facing options for `generate_text` and `stream_text`.
///
/// Unlike `CallOptions` (provider-facing), this does not include `prompt`
/// (passed separately) and defaults are more ergonomic.
///
/// Unknown keys are rejected (RFC-0042 §7.2): a host still writing aimux
/// 0.5's snake_case keys (`max_retries`, `timeout.total_ms`) gets an error
/// naming the key instead of the default it would silently fall back to.
final class Options {
  final double? frequencyPenalty;
  final Map<String, String>? headers;

  /// Emit raw provider stream chunks as `StreamPart::Raw` (debugging aid).
  final bool? includeRawChunks;

  /// System instructions prepended to the prompt.
  final String? instructions;
  final int? maxOutputTokens;

  /// Maximum number of retries, the AI SDK's `maxRetries`; `Some(0)` disables
  /// retrying. `None` uses 2, the AI SDK default.
  final int? maxRetries;

  /// The structured output to generate, the AI SDK's `output`
  /// (`generate-text/output.ts`). It sets the model call's
  /// `response_format` and parses the final text into
  /// [`GenerateTextResult::output`]. `None` sends no response format and
  /// takes the text as the output.
  final Output? output;
  final double? presencePenalty;
  final Map<String, Map<String, Object?>>? providerOptions;

  /// Top-level reasoning effort.
  final ReasoningEffort? reasoning;
  final int? seed;

  /// Session identifier, for grouping consecutive calls into a session
  /// (observability, see RFC-0024). Orthogonal to RFC-0019 session-affinity
  /// headers. When `None` and the optional session inferer is enabled, one
  /// may be inferred from prompt-prefix continuation.
  final String? sessionId;
  final List<String>? stopSequences;
  final double? temperature;

  /// Per-call timeout configuration (total / first-chunk / chunk idle).
  final TimeoutConfiguration? timeout;
  final ToolChoice? toolChoice;
  final List<Tool>? tools;
  final double? topK;
  final double? topP;
  const Options({
    this.frequencyPenalty,
    this.headers,
    this.includeRawChunks,
    this.instructions,
    this.maxOutputTokens,
    this.maxRetries,
    this.output,
    this.presencePenalty,
    this.providerOptions,
    this.reasoning,
    this.seed,
    this.sessionId,
    this.stopSequences,
    this.temperature,
    this.timeout,
    this.toolChoice,
    this.tools,
    this.topK,
    this.topP,
  });
  factory Options.fromJson(Map<String, dynamic> json) {
    return Options(
      frequencyPenalty: json['frequencyPenalty'] == null
          ? null
          : (json['frequencyPenalty'] as num).toDouble(),
      headers: json['headers'] == null
          ? null
          : Map<String, String>.from(json['headers'] as Map),
      includeRawChunks: json['includeRawChunks'] as bool?,
      instructions: json['instructions'] as String?,
      maxOutputTokens: json['maxOutputTokens'] as int?,
      maxRetries: json['maxRetries'] as int?,
      output: json['output'] == null
          ? null
          : Output.fromJson(json['output'] as Map<String, dynamic>),
      presencePenalty: json['presencePenalty'] == null
          ? null
          : (json['presencePenalty'] as num).toDouble(),
      providerOptions: json['providerOptions'] == null
          ? null
          : (json['providerOptions'] as Map).map((key, item) =>
              MapEntry(key as String, Map<String, Object?>.from(item as Map))),
      reasoning: json['reasoning'] == null
          ? null
          : ReasoningEffort.fromJson(json['reasoning']),
      seed: json['seed'] as int?,
      sessionId: json['sessionId'] as String?,
      stopSequences: json['stopSequences'] == null
          ? null
          : (json['stopSequences'] as List).cast<String>(),
      temperature: json['temperature'] == null
          ? null
          : (json['temperature'] as num).toDouble(),
      timeout: json['timeout'] == null
          ? null
          : TimeoutConfiguration.fromJson(
              json['timeout'] as Map<String, dynamic>),
      toolChoice: json['toolChoice'] == null
          ? null
          : ToolChoice.fromJson(json['toolChoice']),
      tools: json['tools'] == null
          ? null
          : (json['tools'] as List)
              .map((item) => Tool.fromJson(item as Map<String, dynamic>))
