  factory Output.fromJson(Map<String, dynamic> json) {
    switch (json['type']) {
      case 'text':
        return OutputText.fromJson(json);
      case 'object':
        return OutputObject.fromJson(json);
      case 'array':
        return OutputArray.fromJson(json);
      case 'choice':
        return OutputChoice.fromJson(json);
      case 'json':
        return OutputJson.fromJson(json);
      default:
        throw FormatException('Unknown Output tag: ${json['type']}');
    }
  }

  Map<String, dynamic> toJson();
}

