          .map((item) => HttpExchange.fromJson(item as Map<String, dynamic>))
          .toList(),
      input: InputRecord.fromJson(json['input'] as Map<String, dynamic>),
      outcome: OutcomeRecord.fromJson(json['outcome'] as Map<String, dynamic>),
      provider:
          ProviderRecord.fromJson(json['provider'] as Map<String, dynamic>),
      recordedAt: json['recordedAt'] as String,
      schema: json['schema'] as int,
      sessionId: json['sessionId'] as String?,
      step: json['step'] as int?,
      transportClosed: json['transportClosed'] as bool,
    );
  }

  Map<String, dynamic> toJson() => {
        'callId': callId,
        'complete': complete,
