/// The output of a tool call (upstream `ToolResultOutput`).
sealed class ToolResultOutput {
  const ToolResultOutput();
  String get type;
  factory ToolResultOutput.fromJson(Map<String, dynamic> json) {
    switch (json['type']) {
      case 'text':
        return ToolResultOutputText.fromJson(json);
      case 'json':
        return ToolResultOutputJson.fromJson(json);
      case 'execution-denied':
        return ToolResultOutputExecutionDenied.fromJson(json);
      case 'error-text':
        return ToolResultOutputErrorText.fromJson(json);
      case 'error-json':
        return ToolResultOutputErrorJson.fromJson(json);
      case 'content':
        return ToolResultOutputContent.fromJson(json);
      default:
        throw FormatException('Unknown ToolResultOutput tag: ${json['type']}');
    }
  }

  Map<String, dynamic> toJson();
}

