/// One probed call. Plaintext never persists — fingerprints only.
final class TraceRecord {
  /// Call-level unique id (association key for Recording / replay,
  /// RFC-0023).
  final String callId;

  /// Error string when the call failed (still recorded: failures are part
  /// of the session).
  final String? error;
  final Fingerprint fingerprint;

  /// Client-side LCP token upper bound (block upper bound, byte-proxy
  /// len/4). `None` when no history matched. Consumed by `TraceStats`
  /// aggregation.
  final int? lcpTokenUpper;
  final String model;
  final String provider;
  final RequestCacheHints? requestCacheHints;
  final String? requestId;

  /// Response-side cache headers (e.g. `x-openrouter-cache-status`).
  final Map<String, String>? responseCacheHeaders;

  /// When the call was sent (epoch ms).
  final int sentAtUnixMs;

  /// The explicit session id of the operation (RFC-0024), else the
  /// layer's default session.
  final String? sessionId;

  /// Time to first streamed token (ms). Non-streaming: `None`.
  final int? ttftMs;
  final UsageSnapshot usage;

  /// Audit verdict (`None` when no auditor is attached — the default).
  final Verdict? verdict;
  const TraceRecord({
    required this.callId,
    this.error,
    required this.fingerprint,
    this.lcpTokenUpper,
    required this.model,
    required this.provider,
    this.requestCacheHints,
    this.requestId,
    this.responseCacheHeaders,
    required this.sentAtUnixMs,
    this.sessionId,
    this.ttftMs,
    required this.usage,
    this.verdict,
  });
  factory TraceRecord.fromJson(Map<String, dynamic> json) {
    return TraceRecord(
      callId: json['callId'] as String,
      error: json['error'] as String?,
      fingerprint:
          Fingerprint.fromJson(json['fingerprint'] as Map<String, dynamic>),
      lcpTokenUpper: json['lcpTokenUpper'] as int?,
      model: json['model'] as String,
      provider: json['provider'] as String,
      requestCacheHints: json['requestCacheHints'] == null
          ? null
          : RequestCacheHints.fromJson(
              json['requestCacheHints'] as Map<String, dynamic>),
      requestId: json['requestId'] as String?,
      responseCacheHeaders: json['responseCacheHeaders'] == null
          ? null
          : Map<String, String>.from(json['responseCacheHeaders'] as Map),
      sentAtUnixMs: json['sentAtUnixMs'] as int,
      sessionId: json['sessionId'] as String?,
      ttftMs: json['ttftMs'] as int?,
      usage: UsageSnapshot.fromJson(json['usage'] as Map<String, dynamic>),
      verdict: json['verdict'] == null
          ? null
          : Verdict.fromJson(json['verdict'] as Map<String, dynamic>),
    );
  }

  Map<String, dynamic> toJson() => {
        'callId': callId,
        if (error != null) 'error': error,
        'fingerprint': fingerprint.toJson(),
        if (lcpTokenUpper != null) 'lcpTokenUpper': lcpTokenUpper,
        'model': model,
        'provider': provider,
        if (requestCacheHints != null)
          'requestCacheHints': requestCacheHints!.toJson(),
        if (requestId != null) 'requestId': requestId,
        if (responseCacheHeaders != null)
          'responseCacheHeaders': responseCacheHeaders,
        'sentAtUnixMs': sentAtUnixMs,
        if (sessionId != null) 'sessionId': sessionId,
        if (ttftMs != null) 'ttftMs': ttftMs,
        'usage': usage.toJson(),
        if (verdict != null) 'verdict': verdict!.toJson(),
      };
}

